from datetime import datetime, timedelta, timezone
from typing import Annotated
import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from jwt.exceptions import InvalidTokenError

SECRET_KEY = "training-only-secret-change-in-production"
ALGORITHM = "HS256"
users = {"alice": "swordfish"}
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")
app = FastAPI()

def create_access_token(subject: str) -> str:
    expires = datetime.now(timezone.utc) + timedelta(minutes=15)
    return jwt.encode({"sub": subject, "exp": expires}, SECRET_KEY, algorithm=ALGORITHM)

def get_current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> str:
    credentials_error = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username = payload.get("sub")
    except InvalidTokenError:
        raise credentials_error
    if not isinstance(username, str) or username not in users:
        raise credentials_error
    return username

@app.post("/token")
async def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]) -> dict[str, str]:
    if users.get(form.username) != form.password:
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    return {"access_token": create_access_token(form.username), "token_type": "bearer"}

@app.get("/users/me")
async def read_me(username: Annotated[str, Depends(get_current_user)]) -> dict[str, str]:
    return {"username": username}

from typing import Annotated
from fastapi import Depends, FastAPI, HTTPException
from fastapi.security import OAuth2PasswordBearer
from pydantic import BaseModel

class User(BaseModel):
    username: str
    disabled: bool = False

users = {
    "alice": User(username="alice"),
    "bob": User(username="bob", disabled=True),
}
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")
app = FastAPI()

def get_current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> User:
    user = users.get(token)
    if user is None:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    return user

def get_current_active_user(user: Annotated[User, Depends(get_current_user)]) -> User:
    if user.disabled:
        raise HTTPException(status_code=400, detail="Inactive user")
    return user

@app.get("/users/me")
async def read_me(user: Annotated[User, Depends(get_current_active_user)]) -> User:
    return user

from datetime import datetime, timedelta, timezone
from typing import Annotated
import jwt
from fastapi import Depends, FastAPI, HTTPException, Security
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm, SecurityScopes
from jwt.exceptions import InvalidTokenError

SECRET_KEY = "training-only-scopes-secret"
ALGORITHM = "HS256"
users = {
    "alice": {"password": "secret", "scopes": ["profile:read", "items:read"]},
    "bob": {"password": "secret", "scopes": ["profile:read"]},
}
oauth2_scheme = OAuth2PasswordBearer(
    tokenUrl="token",
    scopes={"profile:read": "Read your profile", "items:read": "Read items"},
)
app = FastAPI()

def create_token(username: str, scopes: list[str]) -> str:
    payload = {"sub": username, "scopes": scopes, "exp": datetime.now(timezone.utc) + timedelta(minutes=15)}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

def get_current_user(
    security_scopes: SecurityScopes,
    token: Annotated[str, Depends(oauth2_scheme)],
) -> str:
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username = payload.get("sub")
        token_scopes = payload.get("scopes", [])
    except InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if not isinstance(username, str) or username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if any(scope not in token_scopes for scope in security_scopes.scopes):
        raise HTTPException(status_code=403, detail="Not enough permissions")
    return username

@app.post("/token")
async def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]) -> dict[str, str]:
    user = users.get(form.username)
    if user is None or user["password"] != form.password:
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    allowed = set(user["scopes"])
    granted = [scope for scope in form.scopes if scope in allowed]
    return {"access_token": create_token(form.username, granted), "token_type": "bearer"}

@app.get("/profile")
async def profile(username: Annotated[str, Security(get_current_user, scopes=["profile:read"])]) -> dict[str, str]:
    return {"username": username}

@app.get("/items")
async def items(username: Annotated[str, Security(get_current_user, scopes=["items:read"])]) -> dict[str, str]:
    return {"owner": username}

from typing import Annotated
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer

class HTTPBearer403(HTTPBearer):
    def make_not_authenticated_error(self) -> HTTPException:
        return HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Not authenticated",
        )

CredentialsDep = Annotated[
    HTTPAuthorizationCredentials,
    Depends(HTTPBearer403()),
]
app = FastAPI()

@app.get("/me")
def read_me(credentials: CredentialsDep) -> dict[str, str]:
    return {
        "message": "You are authenticated",
        "token": credentials.credentials,
    }
